pub struct Solution;

impl Solution {
    pub fn is_valid(s: String) -> bool {
        let mut stack = Vec::with_capacity(s.len());
        for b in s.bytes() {
            match b {
                b'(' => stack.push(b')'),
                b'[' => stack.push(b']'),
                b'{' => stack.push(b'}'),
                b')' | b']' | b'}' => {
                    if stack.pop() != Some(b) {
                        return false;
                    }
                }
                _ => return false,
            }
        }
        stack.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::Solution;

    #[test]
    fn test_simple_pairs() {
        assert!(Solution::is_valid("()".to_string()));
        assert!(Solution::is_valid("()[]{}".to_string()));
        assert!(!Solution::is_valid("(]".to_string()));
    }

    #[test]
    fn test_nested() {
        assert!(Solution::is_valid("{[]}".to_string()));
        assert!(!Solution::is_valid("([)]".to_string()));
    }

    #[test]
    fn test_unmatched_lengths() {
        assert!(!Solution::is_valid("[".to_string()));
        assert!(!Solution::is_valid("]".to_string()));
        assert!(!Solution::is_valid("(((".to_string()));
        assert!(!Solution::is_valid(")))".to_string()));
    }
}
